CREATE OR REPLACE FUNCTION public.enviar_linea_a_compra(p_pedido_linea_id bigint, p_cantidad_base numeric DEFAULT NULL::numeric, p_motivo text DEFAULT NULL::text, p_usuario text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_l pedido_linea%rowtype; v_pedido pedido%rowtype;
  v_pend numeric; v_cant numeric; v_resto numeric;
  v_cp_nueva numeric; v_sub_nueva numeric;
  v_nueva_id bigint; v_sol_id bigint; v_actor text; v_motivo text;
  v_factor numeric;  -- [2026-10-17]
begin
  if not app_puede_inventariar() then
    raise exception 'Un cajero no puede enviar líneas a compra.' using errcode = '42501';
  end if;

  select * into v_l from pedido_linea where id = p_pedido_linea_id for update;
  if not found then raise exception 'La línea % no existe', p_pedido_linea_id; end if;
  if v_l.es_personalizado then
    raise exception 'Los ítems personalizados ya entran solos a la bandeja de compras';
  end if;
  if v_l.estado not in ('POR_DESPACHAR','PENDIENTE') then
    raise exception 'La línea % está en estado % y no se puede enviar a compra', p_pedido_linea_id, v_l.estado;
  end if;

  select * into v_pedido from pedido where id = v_l.pedido_id for update;
  if v_pedido.estado <> 'ABIERTO' then
    raise exception 'El pedido % está % — no admite enviar líneas a compra', v_l.pedido_id, v_pedido.estado;
  end if;

  v_pend := v_l.cantidad_base - coalesce(v_l.cantidad_despachada, 0);
  v_cant := coalesce(p_cantidad_base, v_pend);
  if v_cant <= 0 then raise exception 'La cantidad a comprar debe ser positiva'; end if;
  if v_cant > v_pend + 0.0001 then
    raise exception 'La cantidad a comprar (%) excede lo pendiente de la línea (%)', v_cant, v_pend;
  end if;
  v_cant := least(v_cant, v_pend);

  -- [2026-10-17] Con presentación (factor > 1) se compra en paquetes enteros:
  -- se redondea hacia arriba, sin pasar de lo pendiente.
  if v_l.presentacion_id is not null then
    select factor_unidad_base into v_factor from presentacion where id = v_l.presentacion_id;
    if v_factor > 1 then
      v_cant := least(ceil(v_cant / v_factor) * v_factor, v_pend);
    end if;
  end if;

  v_actor  := coalesce(p_usuario, auth.jwt() ->> 'email');
  v_motivo := nullif(btrim(p_motivo), '');

  perform guardar_version_pedido(v_l.pedido_id, 'Línea enviada a compra', v_actor);
  perform set_config('roari.compra_origen', 'ALMACEN', true);

  if v_cant >= v_l.cantidad_base - 0.0001 then
    -- Toda la línea (no se despachó nada): la misma línea pasa a POR_COMPRAR.
    update pedido_linea
       set estado = 'POR_COMPRAR', nota = coalesce(v_motivo, nota),
           modificado_por = v_actor, modificado_en = now()
     where id = v_l.id;
    v_nueva_id := v_l.id;
  else
    -- Una parte: línea nueva POR_COMPRAR; la original se achica.
    v_resto := v_l.cantidad_base - v_cant;
    v_cp_nueva := case
      when v_l.presentacion_id is not null and v_l.cantidad_presentacion is not null and v_factor > 0
      then round(v_cant / v_factor, 4)                                    -- [2026-10-17]
      when v_l.presentacion_id is not null and v_l.cantidad_presentacion is not null
      then round(v_l.cantidad_presentacion * v_cant / v_l.cantidad_base, 4)
      else v_cant end;
    v_sub_nueva := case when v_l.subtotal is not null
                        then round(v_l.subtotal * v_cant / v_l.cantidad_base, 2) end;

    insert into pedido_linea (
      pedido_id, producto_id, cantidad_base, estado, sucursal_origen_id,
      presentacion_id, cantidad_presentacion, precio_lista, precio_unitario,
      descuento_pct, subtotal, descripcion, unidad_medida, nota, modificado_por, modificado_en
    ) values (
      v_l.pedido_id, v_l.producto_id, v_cant, 'POR_COMPRAR', v_l.sucursal_origen_id,
      v_l.presentacion_id, v_cp_nueva, v_l.precio_lista, v_l.precio_unitario,
      v_l.descuento_pct, v_sub_nueva, v_l.descripcion, v_l.unidad_medida,
      coalesce(v_motivo, v_l.nota), v_actor, now()
    ) returning id into v_nueva_id;

    update pedido_linea
       set cantidad_base = v_resto,
           cantidad_presentacion = case when v_l.cantidad_presentacion is not null
                                        then v_l.cantidad_presentacion - v_cp_nueva
                                        else cantidad_presentacion end,
           subtotal = case when v_l.subtotal is not null
                           then v_l.subtotal - v_sub_nueva else subtotal end,
           estado = case
             when coalesce(v_l.cantidad_despachada, 0) >= v_resto - 0.0001 then 'DESPACHADA'::estado_linea
             when coalesce(v_l.cantidad_despachada, 0) > 0                  then 'PENDIENTE'::estado_linea
             else 'POR_DESPACHAR'::estado_linea end,
           modificado_por = v_actor, modificado_en = now()
     where id = v_l.id;
  end if;

  -- La solicitud la creó el disparador; acá se completa.
  update compra_solicitud
     set origen = 'ALMACEN', motivo = v_motivo,
         linea_origen_id = case when v_nueva_id <> v_l.id then v_l.id end,
         solicitado_por = coalesce(v_actor, solicitado_por)
   where pedido_linea_id = v_nueva_id and estado in ('SOLICITADA','COMPRADA')
   returning id into v_sol_id;
  if v_sol_id is null then
    raise exception 'No se generó la solicitud de compra para la línea %', v_nueva_id;
  end if;

  update pedido set alerta_lineas_en = now() where id = v_l.pedido_id;
  insert into pedido_evento (pedido_id, accion, motivo, usuario)
  values (v_l.pedido_id, 'LINEA_A_COMPRA', v_motivo, v_actor);
  perform recalcular_estado_pedido(v_l.pedido_id);

  return jsonb_build_object(
    'pedido_id', v_l.pedido_id, 'linea_id', v_l.id, 'linea_compra_id', v_nueva_id,
    'solicitud_id', v_sol_id, 'cantidad_base', v_cant);
end;
$function$
